  class NomConceptoRM extends BaseNomConceptoRM
  {

    /**
     * Obtener un listado de los datos de los conceptos de la retribución monetaria.
     *
     * @param int $inicio Inicio de la busqueda.
     * @param int $limite Limite maximo de la busqueda.
     *
     * @return array    Listado de los datos de los conceptos de la retribución monetaria.
     */
    public static function obtenerListadoConceptosRM($inicio = 0, $limite = 1000)
    {

      //Devolviendo el listado de conceptos en forma de arreglo.
      $query = new Doctrine_Query ();
      $result = (($inicio != null) and ($limite != null))?
      $query->from('NomConceptoRM')
        ->orderBy('denominacion')
        ->limit($limite)
        ->offset($inicio)
        ->fetchArray():
        $query->from('NomConceptoRM')
        ->orderBy('denominacion')
        ->fetchArray();
      return $result;
    }

    /**
     * Obtener la cantidad total de conceptos de la retribución monetaria.
     *
     * @return int      Cantidad total de conceptos de la retribución monetaria.
     */
    public static function obtenerCantidadTotalConceptosRM()
    {

      //Devolviendo la cantidad total de conceptos.
      return Doctrine_Query::create()->select('COUNT(idconceptorm) AS cantidad')
        ->from('NomConceptoRM')
        ->fetchOne()
        ->cantidad;
    }

    /**
     * Obtener un concepto de la retribución monetaria dado el identificador.
     *
     * @param $idconcept        Identificador del concepto.
     *
     * @return NomConceptoRM    Objeto concepto (clase del dominio).
     */
    public static function obtenerObjConceptoRmDadoId($idconcept)
    {
      return Doctrine::getTable('NomConceptoRM')->find($idconcept);
    }

    /**
     * Obtener si existe un concepto de la retribución monetaria a partir de la denominación y la abreviatura.
     *
     * @param int $idconcepto Identificador del concepto de la retribución monetaria.
     * @param string $abrev Abreviatura del concepto de la retribución monetaria.
     * @param string $denom Denominación del concepto de la retribución monetaria.
     *
     * @return boolean          Si existe el del concepto de la retribución monetaria.
     */
    public static function existeConceptoRM($idconcepto, $abrev, $denom)
    {

      $query = Doctrine_Query::create()->select('COUNT(idconceptorm) AS cantidad')
        ->from('NomConceptoRM');
      if ($abrev != '') {
        $query->addWhere("abreviatura ilike ?", $abrev);
      }
      if ($denom != '') {
        $query->addWhere("denominacion ilike ?", $denom);
      }
      if ($idconcepto != '') {
        $query->addWhere('idconceptorm <> ?', $idconcepto);
      }


      return $query->fetchOne()->cantidad > 0;
    }

    /**
     * Funcion para verificar si existe el color
     * @param $denom
     * @param $idtiporeunion
     */
    public function findByIdOrDenom($denom, $idconceptorm = null)
    {
      try {
        $query = Doctrine_Query::create();
        $query->from('NomConceptoRM')
          ->where('fechainicio <= now() and (fechafin is null or fechafin > now())')
          ->andWhere("denominacion ilike '$denom'");
        if (!empty($idconceptorm)) {
          $query->andWhere("idconceptorm <> ?", $idconceptorm);
        }
        $result = $query->count();

        if ($result > 0) {
          return true;
        } else {
          return false;
        }
      } catch (Doctrine_Exception $e) {
        throw $e;
      }
    }


    /************************************VER A PARTIR DE AQUI**************************************/
    public static function obtenerListadoConceptosRMActivos()
    {
      return Doctrine_Query::create()
        ->from('NomConceptoRM')
        ->where('fechafin is null or fechafin <= now()')
        ->fetchArray();
    }

    public static function obtenerListadoConceptosRMDadoArregloIds($arrIds)
    {
      return Doctrine_Query::create()
        ->from('NomConceptoRM')
        ->whereIn('idconceptorm', $arrIds)
        ->fetchArray();
    }

    public static function obtenerDenomXId($idconceptorm)
    {
      return Doctrine_Query::create()->select('p.denominacion AS denominacion')
        ->from('NomConceptoRM p')
        ->where('p.idconceptorm = ?', array($idconceptorm))
        ->fetchOne()
        ->denominacion;
    }

    public static function obtenerConceptoPagoSalario()
    {
      $query  = new Doctrine_Query ();
      $result = $query->from('NomConceptoRM p')
        ->where("p.esconceptopagosalario = ?", array(1))
        ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
        ->execute();
      if (count($result) > 0) {
        return $result[0]['idconceptorm'];
      } else {
        return -1;
      }
    }

    public static function existeDenominacionRM($denominacion, $idconceptorm = null)
