      $query  = new Doctrine_Query ();
      $result = $query->from('NomConceptoRM')
        ->where("denominacion like ?", array($denominacion));

      if (!empty($idconceptorm)) {
        $query->addWhere("idconceptorm <> ?", $idconceptorm);
      }
      $result = $query->count();

      if ($result > 0) {
        return true;
      } else {
        return false;
      }
    }

