        return true;
      } else {
        return false;
      }
    }

    public static function esNeto($id)
    {
      $query  = new Doctrine_Query ();
      $result = $query->from('NomConceptoRM p')
        ->where("p.esconceptopagosalario = ?", array(1))
        ->andwhere("p.idconceptorm = ?", array($id))
        ->setHydrationMode(Doctrine::HYDRATE_ARRAY)
        ->execute();
      if (count($result) > 0) {
        return true;
      } else {
        return false;
      }
    }

    public static function obtenerParrafoFiscal($idconceptorm){
